{
  "driver_archetypes": [
    {
      "id": "car_compliant",
      "base_vclass": "passenger",
      "distribution": "car",
      "share": 0.96,
      "params": {
        "tau": 1.0,
        "minGapLat": 0.6,
        "latAlignment": "center"
      },
      "rationale": "Targets M3/share/car (low red-running) and M2/early/car (low early start); high tau and center alignment reduce risky interactions."
    },
    {
      "id": "car_violator",
      "base_vclass": "passenger",
      "distribution": "car",
      "share": 0.04,
      "params": {
        "tau": 1.5,
        "minGapLat": 0.8,
        "latAlignment": "right"
      },
      "rationale": "Targets M3/share/car (minor contribution to violations) and M2/early/car; slightly lower patience and right alignment mimic occasional aggressive drivers."
    },
    {
      "id": "moto_compliant",
      "base_vclass": "motorcycle",
      "distribution": "moto",
      "share": 0.78,
      "params": {
        "tau": 1.2,
        "minGapLat": 0.6,
        "latAlignment": "center",
        "lcSublane": 0.5,
        "lcPushy": 0.1
      },
      "rationale": "Targets M4/lat_moto and M4/overshoot_share (central stopping position) while allowing slight encroachment for real-world overlap."
    },
    {
      "id": "moto_aggressive",
      "base_vclass": "motorcycle",
      "distribution": "moto",
      "share": 0.22,
      "params": {
        "tau": 1.0,
        "minGapLat": 0.5,
        "latAlignment": "right",
        "lcSublane": 0.8,
        "lcPushy": 0.3,
        "lcAssertive": 2.5
      },
      "rationale": "Targets M4/overshoot_share (high overshoot) and M8/moto (wrong-lane share); tight lateral gap and right alignment mimic aggressive lane filtering."
    },
    {
      "id": "moto_violator",
      "base_vclass": "motorcycle",
      "distribution": "moto",
      "share": 0.12,
      "params": {
        "tau": 1.5,
        "minGapLat": 0.8,
        "latAlignment": "center"
      },
      "rationale": "Targets M6/approach/illegal_l/moto and M7a/n_waiting (illegal left turns); custom1 class allows junction box waiting logic."
    },
    {
      "id": "moto_violator_left",
      "base_vclass": "motorcycle",
      "distribution": "moto",
      "share": 0.18,
      "params": {
        "tau": 1.5,
        "minGapLat": 0.8,
        "latAlignment": "center"
      },
      "rationale": "Targets M6/approach/illegal_l/moto (entry time) and M7a/n_waiting; mirrors moto_violator but with explicit distribution join."
    }
  ],
  "traci_rules": [
    {
      "rule_type": "early_start",
      "applies_to": ["car_compliant", "moto_compliant", "moto_aggressive"],
      "params": {
        "t_before_green": 4,
        "p": 0.15,
        "v_max": 2.0
      },
      "rationale": "Targets M2/early/car and M2/early/moto; moderate probability and short creep window match observed early-start shares."
    },
    {
      "rule_type": "swarm_red_running",
      "applies_to": ["car_compliant", "moto_compliant", "moto_aggressive"],
      "params": {
        "p0": 0.05,
        "k": 0.2,
        "p_max": 0.3,
        "dt": 15
      },
      "rationale": "Targets M3/share/moto and M3/var_to_mean; non-zero base probability and swarm effect reproduce red-light violation rates."
    },
    {
      "rule_type": "queue_space_seeking",
      "applies_to": ["moto_compliant", "moto_aggressive"],
      "params": {
        "q": 50,
        "t_g_s": 10,
        "est_noise": 0.2,
        "p_wrong_lane": 0.25,
        "p_right_lane": 0.15,
        "p_sidewalk": 0.0,
        "v_creep": 3.0,
        "merge_zone_m": 15
      },
      "rationale": "Targets M8/moto (wrong-lane share) and M9a/per_cycle; wrong_lane probability mimics lane filtering behavior observed in Hanoi."
    },
    {
      "rule_type": "illegal_left_box",
      "applies_to": ["moto_violator", "moto_violator_left"],
      "params": {
        "release_lag_s": 0.5
      },
      "rationale": "Targets M6/approach/illegal_l/moto and M7a/release_time; small release lag ensures vehicles exit the box immediately after the opposing green."
    },
    {
      "rule_type": "slow_lane_center",
      "applies_to": ["moto_compliant"],
      "params": {
        "lat_offset": 0.0
      },
      "rationale": "Targets M4/lat_moto; keeps motorcycles centered in the lane while standing, matching observed lateral position."
    },
    {
      "rule_type": "uturn_bypass",
      "applies_to": ["car_compliant", "moto_compliant", "moto_aggressive", "moto_violator"],
      "params": {
        "p": 0.8,
        "t_wait": 5
      },
      "rationale": "Targets M6/junction/s/moto and behavior 11; high bypass probability allows vehicles to squeeze past standing U-turners."
    }
  ]
}

